def _labels_to_name(labels, wildcard=True):
    """bytes 标签列表还原为规范绝对名文本（根为 "."）。

    wildcard 为真时（owner/查询名语境）首标签恰为单字节 0x2A 渲染为
    旧式通配形态 "*"，与既有安全 ASCII 名称输出逐字节一致；其余位置
    及嵌入名（rdata）语境统一渲染为三位十进制 \\042，保证非通配解析
    也能逐字节往返。
    """
    if not labels:
        return "."
